// MRCP Gate Definitions (normalized 0–1 circuit positions)
const GATES = [
  { id: 'G1', name: 'START/FINISH', t: 0.00, color: '#00FF88', missionPhase: 'Race Start — Data Capture' },
  { id: 'G2', name: 'Sector 1 Entry', t: 0.10, color: '#00D4FF', missionPhase: 'Technical Zone — Assessment' },
  { id: 'G3', name: 'Apex A', t: 0.30, color: '#FF6B00', missionPhase: 'Power Sector — Execution' },
  { id: 'G4', name: 'Apex B', t: 0.70, color: '#FF6B00', missionPhase: 'Strategy — Road-Map' },
  { id: 'G5', name: 'Ring Exit', t: 0.90, color: '#00D4FF', missionPhase: 'Final Push — Optimization' },
];

const GATE_PROXIMITY = 0.04; // t-distance threshold
const vehicle = $input.item.json;

// Find which gates vehicle is near
const nearGates = GATES.filter(g => Math.abs(vehicle.circuit_t - g.t) < GATE_PROXIMITY);

if (nearGates.length === 0) return [];

return nearGates.map(g => ({ json: {
  vehicle_id: vehicle.vehicle_id,
  race_id: vehicle.race_id,
  gate_id: g.id,
  gate_name: g.name,
  mission_phase: g.missionPhase,
  gate_color: g.color,
  is_power_sector: g.id === 'G4',
  timestamp_utc: new Date().toISOString()
}}));
